## Config Module

Here's a clean, well-structured configuration module with realistic defaults and validation:

```javascript
// config.js

/**
 * Application configuration module.
 * Values can be overridden via environment variables.
 */

const DEFAULT_CONFIG = {
  host: "localhost",
  port: 3000,
  timeout: 5000,
  retries: 3,
  debug: false,
};

/**
 * Parses and validates a port number.
 * @param {string|number} value - The port value to parse.
 * @returns {number} - A valid port number.
 * @throws {Error} - If the port is out of range.
 */
function parsePort(value) {
  const port = parseInt(value, 10);

  if (isNaN(port) || port < 1 || port > 65535) {
    throw new Error(`Invalid port: "${value}". Must be between 1 and 65535.`);
  }

  return port;
}

/**
 * Parses and validates a timeout value in milliseconds.
 * @param {string|number} value - The timeout value to parse.
 * @returns {number} - A valid timeout in milliseconds.
 * @throws {Error} - If the timeout is negative.
 */
function parseTimeout(value) {
  const timeout = parseInt(value, 10);

  if (isNaN(timeout) || timeout < 0) {
    throw new Error(
      `Invalid timeout: "${value}". Must be a non-negative integer.`
    );
  }

  return timeout;
}

/**
 * Parses and validates a retries count.
 * @param {string|number} value - The retries value to parse.
 * @returns {number} - A valid retries count.
 * @throws {Error} - If retries is negative.
 */
function parseRetries(value) {
  const retries = parseInt(value, 10);

  if (isNaN(retries) || retries < 0) {
    throw new Error(
      `Invalid retries: "${value}". Must be a non-negative integer.`
    );
  }

  return retries;
}

/**
 * Parses a boolean-like value from an environment variable.
 * Accepts "true", "1", "yes" as truthy values (case-insensitive).
 * @param {string} value - The string value to parse.
 * @returns {boolean}
 */
function parseBoolean(value) {
  return ["true", "1", "yes"].includes(value.toLowerCase());
}

/**
 * Builds the config object, merging defaults with environment variables.
 * @returns {Readonly<Object>} - A frozen config object.
 */
function buildConfig() {
  const config = {
    host: process.env.APP_HOST || DEFAULT_CONFIG.host,

    port: process.env.APP_PORT
      ? parsePort(process.env.APP_PORT)
      : DEFAULT_CONFIG.port,

    timeout: process.env.APP_TIMEOUT
      ? parseTimeout(process.env.APP_TIMEOUT)
      : DEFAULT_CONFIG.timeout,

    retries: process.env.APP_RETRIES
      ? parseRetries(process.env.APP_RETRIES)
      : DEFAULT_CONFIG.retries,

    debug: process.env.APP_DEBUG
      ? parseBoolean(process.env.APP_DEBUG)
      : DEFAULT_CONFIG.debug,
  };

  return Object.freeze(config);
}

const config = buildConfig();

export default config;
```

