/**
 * Application configuration module.
 *
 * Values can be overridden via environment variables:
 *   APP_HOST     – hostname or IP of the target service
 *   APP_PORT     – port number
 *   APP_TIMEOUT  – request timeout in milliseconds
 *   APP_RETRIES  – number of retry attempts on failure
 *   APP_DEBUG    – enable verbose debug logging ("true" / "false")
 */

const config = {
  /** Hostname or IP address of the remote service. */
  host: process.env.APP_HOST ?? "localhost",

  /** Port the service listens on. */
  port: parseInt(process.env.APP_PORT ?? "3000", 10),

  /**
   * Maximum time (ms) to wait for a response before aborting.
   * Default: 5 000 ms (5 seconds).
   */
  timeout: parseInt(process.env.APP_TIMEOUT ?? "5000", 10),

  /**
   * Number of times a failed request is retried before giving up.
   * Default: 3 attempts.
   */
  retries: parseInt(process.env.APP_RETRIES ?? "3", 10),

  /**
   * When true, the application emits verbose diagnostic output.
   * Automatically enabled when NODE_ENV is "development".
   */
  debug:
    process.env.APP_DEBUG === "true" ||
    process.env.NODE_ENV === "development",
};

// ── Basic sanity checks ────────────────────────────────────────────────────────

if (config.port < 1 || config.port > 65535) {
  throw new RangeError(`Invalid port: ${config.port}. Must be between 1 and 65535.`);
}

if (config.timeout < 0) {
  throw new RangeError(`Invalid timeout: ${config.timeout}. Must be a non-negative number.`);
}

if (config.retries < 0) {
  throw new RangeError(`Invalid retries: ${config.retries}. Must be a non-negative number.`);
}

// ── Freeze to prevent accidental mutation at runtime ──────────────────────────
Object.freeze(config);

export default config;
