Key design decisions:
- **`??` (nullish coalescing)** is used instead of `||` so that an explicit empty string from the environment is still caught by validation rather than silently replaced.
- **`parseInt` with radix 10** prevents octal mis-parsing of values like `"08"`.
- **`Object.freeze`** makes the exported object immutable, preventing accidental overwrites elsewhere in the codebase.
- **Validation at load time** means misconfiguration fails immediately on startup rather than causing subtle runtime errors later.

```javascript
/**
 * Application configuration module.
 *
 * Values can be overridden through environment variables:
 *   APP_HOST     – hostname or IP of the target service
 *   APP_PORT     – port number
 *   APP_TIMEOUT  – request timeout in milliseconds
 *   APP_RETRIES  – number of retry attempts on failure
 *   APP_DEBUG    – enable verbose debug logging ("true" / "false")
 */

const config = {
  /** Hostname or IP address of the remote service. */
  host: process.env.APP_HOST ?? "localhost",

  /** Port the service listens on. */
  port: Number(process.env.APP_PORT ?? 3000),

  /** Maximum time (ms) to wait for a response before aborting. */
  timeout: Number(process.env.APP_TIMEOUT ?? 5000),

  /** How many times to retry a failed request before giving up. */
  retries: Number(process.env.APP_RETRIES ?? 3),

  /** When true, verbose diagnostic output is written to the console. */
  debug: (process.env.APP_DEBUG ?? "false").toLowerCase() === "true",
};

// ---------------------------------------------------------------------------
// Lightweight validation – catch obvious mis-configurations at startup.
// ---------------------------------------------------------------------------

if (!config.host || typeof config.host !== "string") {
  throw new Error(`[config] Invalid host: "${config.host}"`);
}

if (!Number.isInteger(config.port) || config.port < 1 || config.port > 65535) {
  throw new Error(
    `[config] Port must be an integer between 1 and 65535, got: ${config.port}`
  );
}

if (!Number.isFinite(config.timeout) || config.timeout < 0) {
  throw new Error(
    `[config] Timeout must be a non-negative number, got: ${config.timeout}`
  );
}

if (!Number.isInteger(config.retries) || config.retries < 0) {
  throw new Error(
    `[config] Retries must be a non-negative integer, got: ${config.retries}`
  );
}

if (typeof config.debug !== "boolean") {
  throw new Error(`[config] Debug must be a boolean, got: ${config.debug}`);
}

// ---------------------------------------------------------------------------
// Freeze the object so callers cannot accidentally mutate shared state.
// ---------------------------------------------------------------------------

Object.freeze(config);

export default config;
```

