```javascript
/**
 * Application configuration module.
 *
 * Values are resolved in the following priority order:
 *   1. Environment variables (runtime overrides)
 *   2. Hard-coded defaults (fallback)
 *
 * Environment variables recognised:
 *   APP_HOST     – hostname or IP the service binds to
 *   APP_PORT     – TCP port number (integer)
 *   APP_TIMEOUT  – request timeout in milliseconds (integer)
 *   APP_RETRIES  – maximum retry attempts on failure (integer)
 *   APP_DEBUG    – enable verbose logging ("true" / "1" to enable)
 */

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * Parse an environment variable as an integer.
 * Returns `defaultValue` when the variable is absent or not a valid integer.
 *
 * @param {string}  name         - Environment variable name.
 * @param {number}  defaultValue - Fallback value.
 * @returns {number}
 */
function envInt(name, defaultValue) {
  const raw = process.env[name];
  if (raw === undefined || raw.trim() === "") return defaultValue;

  const parsed = Number.parseInt(raw, 10);
  if (Number.isNaN(parsed)) {
    console.warn(
      `[config] Expected an integer for ${name} but got "${raw}". ` +
        `Using default: ${defaultValue}`
    );
    return defaultValue;
  }

  return parsed;
}

/**
 * Parse an environment variable as a boolean.
 * Treats "true" and "1" (case-insensitive) as `true`; everything else as `false`.
 * Returns `defaultValue` when the variable is absent.
 *
 * @param {string}  name         - Environment variable name.
 * @param {boolean} defaultValue - Fallback value.
 * @returns {boolean}
 */
function envBool(name, defaultValue) {
  const raw = process.env[name];
  if (raw === undefined) return defaultValue;
  return raw.trim().toLowerCase() === "true" || raw.trim() === "1";
}

/**
 * Read a string environment variable.
 * Returns `defaultValue` when the variable is absent or empty.
 *
 * @param {string} name         - Environment variable name.
 * @param {string} defaultValue - Fallback value.
 * @returns {string}
 */
function envString(name, defaultValue) {
  const raw = process.env[name];
  return raw !== undefined && raw.trim() !== "" ? raw.trim() : defaultValue;
}

// ---------------------------------------------------------------------------
// Validation
// ---------------------------------------------------------------------------

/**
 * Validate a resolved config object and throw on obviously wrong values.
 *
 * @param {{ host: string, port: number, timeout: number, retries: number, debug: boolean }} cfg
 */
function validate(cfg) {
  if (!cfg.host) {
    throw new Error("[config] `host` must be a non-empty string.");
  }

  if (cfg.port < 1 || cfg.port > 65_535) {
    throw new RangeError(
      `[config] \`port\` must be between 1 and 65535 (got ${cfg.port}).`
    );
  }

  if (cfg.timeout < 0) {
    throw new RangeError(
      `[config] \`timeout\` must be a non-negative integer (got ${cfg.timeout}).`
    );
  }

  if (cfg.retries < 0) {
    throw new RangeError(
      `[config] \`retries\` must be a non-negative integer (got ${cfg.retries}).`
    );
  }
}

// ---------------------------------------------------------------------------
// Config object
// ---------------------------------------------------------------------------

/**
 * @typedef {Object} AppConfig
 * @property {string}  host    - Hostname or IP address the server listens on.
 * @property {number}  port    - TCP port number.
 * @property {number}  timeout - Request timeout in milliseconds.
 * @property {number}  retries - Maximum number of retry attempts.
 * @property {boolean} debug   - Whether verbose/debug logging is enabled.
 */

/** @type {AppConfig} */
const config = Object.freeze({
  /** Hostname / IP the service binds to. */
  host: envString("APP_HOST", "127.0.0.1"),

  /** TCP port the HTTP server listens on. */
  port: envInt("APP_PORT", 3000),

  /**
   * Maximum time (ms) to wait for a response before aborting.
   * Default: 5 000 ms (5 seconds).
   */
  timeout: envInt("APP_TIMEOUT", 5_000),

  /**
   * How many times a failed request is retried before giving up.
   * Default: 3 attempts.
   */
  retries: envInt("APP_RETRIES", 3),

  /**
   * Enable verbose logging.
   * Default: false in production, true otherwise.
   */
  debug: envBool(
    "APP_DEBUG",
    process.env.NODE_ENV !== "production" // smart default
  ),
});

validate(config);

export default config;
```

