## Config Module

Here's a clean, well-structured configuration module with realistic defaults and validation:

```javascript
// config.js

/**
 * Application configuration module.
 * Values can be overridden via environment variables.
 */

const DEFAULT_CONFIG = {
  host: "localhost",
  port: 3000,
  timeout: 5000,   // milliseconds
  retries: 3,
  debug: false,
};

/**
 * Parses and validates a port number.
 * @param {string|number} value
 * @returns {number}
 */
function parsePort(value) {
  const port = parseInt(value, 10);
  if (isNaN(port) || port < 1 || port > 65535) {
    throw new RangeError(`Invalid port: "${value}". Must be between 1 and 65535.`);
  }
  return port;
}

/**
 * Parses and validates a positive integer.
 * @param {string|number} value
 * @param {string} fieldName
 * @returns {number}
 */
function parsePositiveInt(value, fieldName) {
  const parsed = parseInt(value, 10);
  if (isNaN(parsed) || parsed < 0) {
    throw new TypeError(`Invalid ${fieldName}: "${value}". Must be a non-negative integer.`);
  }
  return parsed;
}

/**
 * Parses a boolean from various input types.
 * @param {string|boolean} value
 * @returns {boolean}
 */
function parseBoolean(value) {
  if (typeof value === "boolean") return value;
  return value === "true" || value === "1";
}

/**
 * Builds the config object, merging defaults with environment variables.
 * @returns {Readonly<object>}
 */
function buildConfig() {
  const config = {
    host:    process.env.APP_HOST    ?? DEFAULT_CONFIG.host,
    port:    process.env.APP_PORT
               ? parsePort(process.env.APP_PORT)
               : DEFAULT_CONFIG.port,
    timeout: process.env.APP_TIMEOUT
               ? parsePositiveInt(process.env.APP_TIMEOUT, "timeout")
               : DEFAULT_CONFIG.timeout,
    retries: process.env.APP_RETRIES
               ? parsePositiveInt(process.env.APP_RETRIES, "retries")
               : DEFAULT_CONFIG.retries,
    debug:   process.env.APP_DEBUG !== undefined
               ? parseBoolean(process.env.APP_DEBUG)
               : DEFAULT_CONFIG.debug,
  };

  return Object.freeze(config);
}

const config = buildConfig();

export default config;

// Named export for flexibility
export { config };
```

