const { host, port, timeout, retries, debug } = config;

console.log(`Connecting to ${host}:${port} (timeout: ${timeout}ms, retries: ${retries})`);
// → "Connecting to localhost:3000 (timeout: 5000ms, retries: 3)"
```

---

### Key Design Decisions

| Decision | Reason |
|---|---|
| `Object.freeze()` | Prevents accidental mutation at runtime |
| Environment variable overrides | Follows the [12-Factor App](https://12factor.net/config) methodology |
| Input validation with clear errors | Fails fast with descriptive messages instead of silent bugs |
| Separate `DEFAULT_CONFIG` constant | Single source of truth for defaults, easy to audit |
| Named + default export | Gives consumers flexibility in how they import |

```javascript
/**
 * Application configuration module.
 *
 * Values can be overridden via environment variables:
 *   APP_HOST     – hostname or IP address of the target server
 *   APP_PORT     – port number the server listens on
 *   APP_TIMEOUT  – request timeout in milliseconds
 *   APP_RETRIES  – number of retry attempts on failure
 *   APP_DEBUG    – enable verbose debug logging ("true" / "false")
 */

const config = {
  /** Hostname or IP address of the target server. */
  host: process.env.APP_HOST ?? "localhost",

  /** Port the server listens on (1–65535). */
  port: Number(process.env.APP_PORT ?? 3000),

  /**
   * Maximum time (ms) to wait for a response before aborting.
   * Default: 5 000 ms (5 seconds).
   */
  timeout: Number(process.env.APP_TIMEOUT ?? 5000),

  /**
   * How many times a failed request is retried before giving up.
   * Default: 3 attempts.
   */
  retries: Number(process.env.APP_RETRIES ?? 3),

  /**
   * When true, the application emits verbose diagnostic output.
   * Automatically enabled when NODE_ENV is "development".
   */
  debug:
    process.env.APP_DEBUG !== undefined
      ? process.env.APP_DEBUG === "true"
      : process.env.NODE_ENV === "development",
};

// ── Basic sanity checks ────────────────────────────────────────────────────────

if (!Number.isInteger(config.port) || config.port < 1 || config.port > 65535) {
  throw new RangeError(`Invalid port: "${config.port}". Must be an integer between 1 and 65535.`);
}

if (!Number.isFinite(config.timeout) || config.timeout <= 0) {
  throw new RangeError(`Invalid timeout: "${config.timeout}". Must be a positive number.`);
}

if (!Number.isInteger(config.retries) || config.retries < 0) {
  throw new RangeError(`Invalid retries: "${config.retries}". Must be a non-negative integer.`);
}

// ── Freeze so callers cannot mutate shared state ───────────────────────────────

Object.freeze(config);

export default config;
```

---

### How it works

| Field | Default | Environment variable | Type |
|---|---|---|---|
| `host` | `"localhost"` | `APP_HOST` | `string` |
| `port` | `3000` | `APP_PORT` | `number` |
| `timeout` | `5000` (ms) | `APP_TIMEOUT` | `number` |
| `retries` | `3` | `APP_RETRIES` | `number` |
| `debug` | `false` (or `true` in dev) | `APP_DEBUG` | `boolean` |

### Key design decisions

- **Environment variables** – every field can be overridden at runtime without touching source code, which is the standard 12-factor approach.
- **Nullish coalescing (`??`)** – falls back to the default only when the env var is `undefined` or `null`, not when it is an empty string (which would be a misconfiguration worth catching).
- **Explicit `Number()` conversion** – environment variables are always strings; coercing them explicitly avoids silent `NaN` bugs.
- **`debug` logic** – `APP_DEBUG` takes priority; if it is absent, the flag mirrors `NODE_ENV === "development"` so developers get logging automatically.
- **Validation** – invalid values throw immediately at startup rather than causing mysterious failures later.
- **`Object.freeze`** – prevents accidental mutation of the shared config object elsewhere in the codebase.

### Usage

```javascript
import config from "./config.js";

console.log(config.host);    // "localhost"
console.log(config.port);    // 3000
console.log(config.timeout); // 5000
console.log(config.retries); // 3
console.log(config.debug);   // false (true when NODE_ENV=development)
```

