/**
 * @file Application configuration.
 * @description Exports a configuration object with default settings for the application.
 * These values can be overridden by environment variables or other configuration methods.
 */

/**
 * @typedef {object} AppConfig
 * @property {string} host - The hostname or IP address to connect to.
 * @property {number} port - The port number to connect to.
 * @property {number} timeout - The request timeout in milliseconds.
 * @property {number} retries - The number of times to retry a failed request.
 * @property {boolean} debug - A flag to enable or disable debug mode.
 */

/** @type {AppConfig} */
const config = {
  /**
   * The server host.
   * Default is 'localhost' for local development.
   */
  host: 'localhost',

  /**
   * The server port.
   * 8080 is a common alternative to 80 for development servers.
   */
  port: 8080,

  /**
   * Request timeout in milliseconds.
   * 5000ms (5 seconds) is a reasonable default to prevent long-running requests
   * from hanging the application.
   */
  timeout: 5000,

  /**
   * Number of retries for a failed operation.
   * 3 is a common value to handle transient network errors.
   */
  retries: 3,

  /**
   * Debug mode flag.
   * Should be `false` in production to avoid leaking sensitive information
   * and to improve performance.
   */
  debug: false,
};

export default config;
```

---

### Breakdown of Choices

*   **`host: 'localhost'`**: This is the standard hostname for services running on the local machine, perfect for a development default.
*   **`port: 8080`**: A very common port for development web servers and APIs. It's in the "unprivileged" port range (> 1024), so it doesn't require special permissions to run.
*   **`timeout: 5000`**: 5 seconds is a sensible default for network requests. It's long enough to accommodate a slow connection but short enough to prevent a poor user experience if a service is unresponsive. The comment clarifies that the unit is milliseconds.
*   **`retries: 3`**: Retrying a failed request 3 times is a common strategy to overcome temporary issues like network hiccups or brief server unavailability.
*   **`debug: false`**: The safest default is to have debugging disabled. It should be explicitly enabled only during development or troubleshooting.
*   **`export default`**: This makes the `config` object the primary, default export from this file, which is a common pattern for configuration modules.
*   **JSDoc Comments**: The comments (`/** ... */`) provide excellent documentation, making the code easier to understand and enabling better autocompletion in modern code editors like VS Code.

