   * avoiding the need for special permissions.
   * @type {number}
   */
  port: 8080,

  /**
   * The timeout for network requests, in milliseconds.
   * 5000ms (5 seconds) is a reasonable default to prevent indefinite waiting.
   * @type {number}
   */
  timeout: 5000,

  /**
   * The number of times to retry a failed connection.
   * 3 is a sensible number for handling transient network issues.
   * @type {number}
   */
  retries: 3,

  /**
